import {mergeAsset} from './asset-merge.js';
export class AssetMergePanel{
 constructor(element,{base,ours,theirs,validate,apply,error=()=>{},baseFromGit}){Object.assign(this,{element,base,ours,theirs,validate,apply,error,baseFromGit});this.resolutions={};this.page=0;this.render();}
 result(){return mergeAsset(this.base,this.ours,this.theirs,{resolutions:this.resolutions});}
 choose(id,choice){this.resolutions[id]=choice;this.render();}
 async loadFile(which){const document=this.element.ownerDocument,input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>8388608)throw Error('병합 JSON은8MB까지 지원해요.');this[which]=JSON.parse(await file.text());this.resolutions={};this.page=0;this.render();}catch(e){this.error(e.message);}};input.click();}
 render(){
  if(this.disposed)return;const document=this.element.ownerDocument;this.element.className='workspace-view source-control-panel';this.element.replaceChildren();const header=document.createElement('header');header.className='document-toolbar';const button=(parent,label,action,disabled=false)=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.disabled=disabled;b.onclick=action;parent.append(b);return b;};button(header,'기준 가져오기',()=>this.loadFile('base'));if(this.baseFromGit)button(header,'Git 기준',async()=>{try{this.base=await this.baseFromGit();this.resolutions={};this.render();}catch(e){this.error(e.message);}});button(header,'다른 버전 가져오기',()=>this.loadFile('theirs'));button(header,'선택 초기화',()=>{this.resolutions={};this.render();});this.element.append(header);const body=document.createElement('div');body.className='asset-form';body.style.overflow='auto';this.element.append(body);let result;
  try{result=this.result();}catch(e){const message=document.createElement('p');message.textContent=e.message;body.append(message);return;}
  const summary=document.createElement('h3');summary.textContent='남은 충돌 '+result.conflicts.length+' · 선택 '+result.resolved.length;body.append(summary);const actions=document.createElement('div');actions.className='asset-merge-actions';body.append(actions);for(const [label,choice]of [['현재 버전 선택','ours'],['다른 버전 선택','theirs']])button(actions,label,()=>{for(const conflict of result.conflicts)this.resolutions[conflict.id]=choice;this.render();},!result.conflicts.length);
  let valid=false;try{valid=this.validate(result.data);}catch{}button(actions,'문서에 적용',async()=>{try{await this.apply(result.data);const notice=document.createElement('small');notice.textContent='문서에 적용됨';actions.append(notice);}catch(e){this.error(e.message);}},!result.clean||!valid);
  this.page=Math.min(this.page,Math.max(0,Math.ceil(result.conflicts.length/20)-1));const navigation=document.createElement('div');navigation.className='asset-merge-actions';button(navigation,'이전',()=>{this.page--;this.render();},this.page===0);const number=document.createElement('span');number.textContent=(this.page+1)+' / '+Math.max(1,Math.ceil(result.conflicts.length/20));navigation.append(number);button(navigation,'다음',()=>{this.page++;this.render();},(this.page+1)*20>=result.conflicts.length);body.append(navigation);
  for(const row of result.conflicts.slice(this.page*20,this.page*20+20)){const section=document.createElement('section');section.className='asset-merge-conflict';const title=document.createElement('h3');title.textContent=row.id;section.append(title);const columns=document.createElement('div');columns.className='asset-merge-values';for(const [key,label,exists]of [['base','기준',row.hasBase],['ours','현재',row.hasOurs],['theirs','다른 버전',row.hasTheirs]]){const column=document.createElement('div'),heading=document.createElement('strong'),pre=document.createElement('pre');heading.textContent=label;pre.textContent=exists?JSON.stringify(row[key],null,2).slice(0,32768):'삭제';column.append(heading,pre);button(column,'선택',()=>this.choose(row.id,key));columns.append(column);}section.append(columns);body.append(section);}
 }
 dispose(){this.disposed=true;this.element.replaceChildren();this.base=this.ours=this.theirs=null;this.resolutions={};}
}
